class Investment { public: virtual ~Investment() = default; virtual void trade() = 0; };
class Stock : public Investment { public: void trade() override; };
class Bond : public Investment { public: void trade() override; };

// Custom deleter that logs before deleting.
auto loggingDeleter = [](Investment* inv) {
    std::cout << "Deleting investment...\n";
    delete inv;
};

// Factory returns a unique_ptr with the custom deleter's type encoded.
std::unique_ptr<Investment, decltype(loggingDeleter)> 
makeInvestment(const std::string& type) {
    std::unique_ptr<Investment, decltype(loggingDeleter)> pInv(nullptr, loggingDeleter);
    if (type == "stock") {
        pInv.reset(new Stock());
    }
    else if (type == "bond") {
        pInv.reset(new Bond());
    }
    return pInv; // Ownership is moved to the caller.
}

// Client code is simple and clean.
auto myInvestment = makeInvestment("stock");
if (myInvestment) {
    myInvestment->trade();
} 
// At end of scope, loggingDeleter is automatically called.
